$ErrorActionPreference='Stop';$source='C:\Users\Z4 G4\Documents\CFA\CFA Premium pack\CFA Premium pack (2026)';$output=New-Item -ItemType Directory -Force '.local-research\mock-exams\library-rescan\premium-pages';$tesseract='C:\Program Files\Tesseract-OCR\tesseract.exe'
Add-Type -AssemblyName System.Runtime.WindowsRuntime
[Windows.Storage.StorageFile,Windows.Storage,ContentType=WindowsRuntime]|Out-Null;[Windows.Data.Pdf.PdfDocument,Windows.Data.Pdf,ContentType=WindowsRuntime]|Out-Null;[Windows.Data.Pdf.PdfPageRenderOptions,Windows.Data.Pdf,ContentType=WindowsRuntime]|Out-Null;[Windows.Storage.Streams.InMemoryRandomAccessStream,Windows.Storage.Streams,ContentType=WindowsRuntime]|Out-Null
$generic=[System.WindowsRuntimeSystemExtensions].GetMethods()|Where-Object{$_.Name-eq'AsTask'-and$_.IsGenericMethod-and$_.GetParameters().Count-eq 1}|Select-Object -First 1;$action=[System.WindowsRuntimeSystemExtensions].GetMethods()|Where-Object{$_.Name-eq'AsTask'-and-not$_.IsGenericMethod-and$_.GetParameters().Count-eq 1}|Select-Object -First 1
function Result($operation,[Type]$type){$task=$generic.MakeGenericMethod($type).Invoke($null,@($operation));$task.Wait();$task.Result};function Done($operation){$task=$action.Invoke($null,@($operation));$task.Wait()}
foreach($file in Get-ChildItem -LiteralPath $source -Filter *.pdf|Sort-Object Name){$slug=($file.BaseName-replace'[^a-zA-Z0-9]+','-').Trim('-');$storage=Result ([Windows.Storage.StorageFile]::GetFileFromPathAsync($file.FullName)) ([Windows.Storage.StorageFile]);$pdf=Result ([Windows.Data.Pdf.PdfDocument]::LoadFromFileAsync($storage)) ([Windows.Data.Pdf.PdfDocument]);foreach($index in 0..($pdf.PageCount-1)){$text=Join-Path $output.FullName "$slug-page-$($index+1).txt";if(Test-Path $text){continue};$png=$text-replace'\.txt$','.png';$page=$pdf.GetPage($index);$stream=New-Object Windows.Storage.Streams.InMemoryRandomAccessStream;$options=New-Object Windows.Data.Pdf.PdfPageRenderOptions;$options.DestinationWidth=1600;Done ($page.RenderToStreamAsync($stream,$options));$reader=New-Object Windows.Storage.Streams.DataReader($stream.GetInputStreamAt(0));$count=Result ($reader.LoadAsync([uint32]$stream.Size)) ([uint32]);$bytes=New-Object byte[] $count;$reader.ReadBytes($bytes);[IO.File]::WriteAllBytes($png,$bytes);$reader.Dispose();$stream.Dispose();$page.Dispose();$old=$ErrorActionPreference;$ErrorActionPreference='Continue';&$tesseract $png ($text-replace'\.txt$','') -l eng 2>$null;$code=$LASTEXITCODE;$ErrorActionPreference=$old;Remove-Item $png;if($code-ne 0){throw "OCR failed: $($file.Name), page $($index+1)"}};Write-Host "Inspected $($file.Name) ($($pdf.PageCount) pages)"}
